fn main() {
    // Attempt to move a reference into a function expecting an owned String
    let s = "hello";
    let r = &s;

    // This would fail to compile if uncommented:
    // let owned = r.to_string(); // Error: cannot move a reference into a function expecting an owned String

    // Implement a function taking a reference
    fn process_string_ref(s: &str) -> String {
        format!("Processed: {}", s)
    }

    // Assert that the function call with a reference succeeds
    let result = process_string_ref(r);
    assert_eq!(result, "Processed: hello");

    println!("Ownership test passed");
}
